"""Illustrated walkthrough of the current localhost acceptance flow."""
from guide_layout import Guide, H, INK, LINE, PALE
from reportlab.lib.units import mm
from reportlab.platypus import Table, TableStyle, Paragraph
from reportlab.lib.styles import ParagraphStyle

g = Guide('Srez_local_testing.pdf', 'Проверка локальной версии', 5)
t = g.start('1. Подготовьте учебный магазин')
t = g.note('<b>http://localhost:8099/</b><br/>Обычное окно - видеоконтроль. Окно инкогнито - продавец. Это независимые сеансы на одном компьютере. Уведомления Telegram и MAX здесь выключены.', t)+5
t = g.step(1, 'Нажмите <b>«Видеоконтроль» → «Магазины и сотрудники» → «Добавить магазин»</b>. Название и код выберите свои.', t)
t = g.step(2, 'Начало учёта - <b>сегодня</b>. Для примера: Москва, 10:00-22:00, все рабочие дни. Сохраните. В первый день локального примера все три отчёта доступны сразу.', t)
t = g.step(3, 'В строке магазина нажмите сумму <b>«План на день»</b>. Укажите: <b>10 000 рублей, 20 чеков, 40 алкогольных единиц</b>. Сохраните.', t)+3
t = g.shot('guide-plan', t, width=130, maxheight=104)+3
g.note('Для нового прохождения создайте свой магазин. Уже заполненный пример <b>CHECK-001</b> можно посмотреть за <b>18.09.2026</b>.', t)

t = g.start('2. Добавьте продавца и дайте вход')
t = g.step(1, '<b>«Добавить сотрудника»</b> → ФИО → сохранить. У магазина нажмите <b>«Настроить»</b> и выберите это ФИО в «Продавец 1».', t)
t = g.step(2, 'В строке сотрудника нажмите <b>«Доступ»</b>. Найдите магазин по <b>коду или названию</b>, отметьте его и нажмите <b>«Создать ссылку»</b>. Затем <b>«Скопировать ссылку»</b>.', t)
t = g.shot('guide-access-links', t+2, width=120, maxheight=157)+3
g.note('Отправьте ссылку продавцу в личном сообщении. Он откроет её и войдёт <b>без логина и пароля</b>. Для проверки откройте ссылку в инкогнито на этом компьютере. Видны только разрешённые магазины.', t)

t = g.start('3. Продавец заполняет три отчёта')
t = g.step(1, 'Выберите сегодняшнюю дату и <b>13:00</b>. Введите первую строку примера ниже. Нажмите <b>«Сохранить отчёт»</b> и дождитесь подтверждения.', t)
t = g.step(2, 'Повторите для <b>17:00</b> и <b>закрытия</b>. Вводятся итоги с начала дня. Проценты под полями меняются ещё при вводе.', t)+3
style = ParagraphStyle('cell', fontName='Guide',fontSize=10,leading=13,textColor=INK)
rows = [
    ['Срез', 'Выручка / %', 'Чеки / %', 'Единицы / %'],
    ['13:00', '2 500 / 25%', '6 / 30%', '8 / 20%'],
    ['17:00', '7 000 / 70%', '15 / 75%', '28 / 70%'],
    ['Закрытие', '11 000 / 110%', '22 / 110%', '44 / 110%'],
]
table=Table([[Paragraph(x,style) for x in row] for row in rows],colWidths=[34*mm,48*mm,46*mm,48*mm])
table.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),PALE),('GRID',(0,0),(-1,-1),.5,LINE),('TOPPADDING',(0,0),(-1,-1),9),('BOTTOMPADDING',(0,0),(-1,-1),9)]))
_,height=table.wrap(176*mm,260*mm);table.drawOn(g.c,17*mm,H-t*mm-height);t+=height/mm+5
t = g.note('Для этой таблицы дневные планы: <b>10 000 рублей / 20 чеков / 40 единиц</b>. Процент каждого среза считается от этих дневных планов. 110% означает перевыполнение.',t)+5
t = g.shot('guide-seller-inputs',t,width=176,caption='Под каждым полем - соответствующий дневной план и его выполнение')+4
g.p('В блоке <b>«Отчёты за день»</b> видны сохранённые цифры и проценты на все три времени. Пустой отчёт не считается нулевой продажей; отсутствующий или нулевой план не даёт ложные 0%.',t)

t = g.start('4. Видеоконтроль проверяет цифры')
t = g.step(1, 'В обычном окне откройте <b>«Отчёты»</b> и найдите магазин. Обновление происходит примерно раз в 15 секунд; кнопка <b>«Обновить»</b> находится внизу.',t)
t = g.step(2, 'Слева - три дневных плана. Дальше - 13:00, 17:00 и <b>«Закрытие · итог дня»</b>. Под каждым фактом - его процент. Сверьте значения со страницей 3.',t)+3
t = g.shot('guide-office-plans',t,width=176,caption='Фрагмент таблицы: дневные планы и первый срез')+5
t = g.step(3, '<b>«Скачать таблицу»</b> → Excel или CSV. Выгружаются найденные магазины, три плана, девять фактов и девять процентов. Кнопки <b>«% плана»</b> позволяют искать и сортировать по процентам.',t)
t = g.step(4, 'Для проверки истории измените выручку на закрытие с 11 000 на <b>11 200</b>, добавьте причину и сохраните. По выручке получится <b>112%</b>. В обсуждении откройте <b>историю изменений</b>: прежняя версия остаётся, указан тот, кто внёс правку.',t)+3
g.note('Если отчёт не отправлен, ячейки пустые. При известном истёкшем сроке появится «Не сдан». У нового локального магазина в первый день просроченность задним числом не назначается.',t)

t = g.start('5. Вопросы и проверка доступа')
t = g.step(1, 'У продавца: выберите время → <b>«Задать вопрос видеоконтролю / история отчёта»</b> над формой → напишите текст → <b>«Отправить сообщение»</b>.',t)
t = g.step(2, 'У офиса: <b>«Есть вопрос»</b> → значок сообщения справа у магазина → прочитайте и ответьте. Продавец увидит <b>«Сообщение от видеоконтроля»</b>. После ответа офис нажимает <b>«Вопрос решён»</b>.',t)+3
t = g.shot('guide-conversation',t,width=150,maxheight=95,caption='Проверенная переписка продавца и офиса')+3
t = g.step(3, 'Сотрудник → <b>«Доступ»</b> → снять <b>«Вход на сайт разрешён»</b> → сохранить. Вход закроется. <b>«Заменить ссылку»</b> отключает старую ссылку и прежние сеансы; новую отправьте продавцу.',t)
t = g.step(4, '<b>«Удалить»</b> сохраняет историю. Для возврата включите <b>«Показывать удалённые…»</b> и нажмите <b>«Восстановить»</b>. После восстановления сотрудника отдельно разрешите ему вход.',t)+2
g.note('Проверены: создание, вход по ссылке, её замена и отключение, поиск магазинов, отчёты, проценты, переписка, исправления, история и CSV/Excel. Пройдены 45 серверных проверок и сборка. Внешняя отправка ботами в этот локальный тест не входит.',t,size=9.5)
g.finish()
print('Created output/pdf/Srez_local_testing.pdf')
